sys_script_fix.script:
var client = new GlideRecord('sys_cs_adapter_configuration_page');
client.query();
while(client.next()){
	var attribute = new GlideRecord('sys_cs_adapter_configuration');
	attribute.setValue('sys_cs_adapter_configuration_page', client.getUniqueValue());
	attribute.setValue('attribute_name', 'live_agent_keyword');
	attribute.setValue('attribute_value', 'Agent');	
	attribute.insert();
}
